import { useState, StrictMode, useCallback, useEffect } from "react";
import { createRoot } from "react-dom/client";
import { ComponentContext, getStudioProApi, IComponent, StudioProApi } from "@mendix/extensions-api";
import { Tool, ToolType } from "../../types/tool";
import { createNewTool } from "../../utils/toolUtils";
import { PageContent, ContentColumn, PageContainerDialog } from "../components/PageContainers";
import AppThemeProvider from "../components/AppThemeProvider";
import FormDivider from "../components/FormDivider"
import TextInputLabeled from "../components/TextInputLabeled";
import { DropdownListBoxItem } from "@mendix/ide-ui-components/dropdown/dropdown/DropdownListBox";
import { ComboBox } from "@mendix/ide-ui-components/dropdown/combobox/ComboBox";
import TextAreaLabeled from "../components/TextAreaLabeled";
import DialogFooter from "../components/DialogFooter";
import { handleSelectCustomDocument, handleValidateTool } from "./toolHandlers";
import TextInputWithButton from "../components/TextInputWithButton";
import { MicroflowIcon } from "@mendix/ide-icons/MicroflowIcon";
import { handleShowMicroflow } from "../../utils/microflowUtils";
import { createStudioProLogger } from "../../config/logger";
import { Agent } from "../../types/agent";

interface AppProps {
    studioPro: StudioProApi;
    initialTool?: Tool;
    agent: Agent;
    onClose?: (result: Tool | null) => void;
}

type ValidationInfo = {
    isValidName: true | string;
    isValidDescription: true | string;
    isValidMicroflow: true | string;
    isValidType: true | string;
}

const initialValidationInfo: ValidationInfo = {
    isValidName: true,
    isValidDescription: true,
    isValidMicroflow: true,
    isValidType: true
}


const toolTypeOptions: { key: ToolType; caption: string }[] = [
    { key: "Microflow", caption: "Microflow tool" }
]

const fieldToValidationKey: Partial<Record<keyof Tool, keyof ValidationInfo>> = {
    name: 'isValidName',
    description: 'isValidDescription',
    microflow: 'isValidMicroflow',
    toolType: 'isValidType'
};

const App: React.FC<AppProps> = ({ studioPro, initialTool, agent, onClose }) => {

    const [tool, setTool] = useState(initialTool || createNewTool());
    const [validationInfo, setValidationInfo] = useState(initialValidationInfo);

    const validateTool = useCallback(async (tool: Tool): Promise<ValidationInfo> => {
        return {
            isValidName: await handleValidateTool("name", tool, studioPro, agent),
            isValidDescription: await handleValidateTool("description", tool, studioPro, agent),
            isValidMicroflow: await handleValidateTool("microflow", tool, studioPro, agent),
            isValidType: await handleValidateTool("toolType", tool, studioPro, agent),
        }
    }, [studioPro, agent]);
    
    const handleOk = useCallback(async () => {
        // Validate all fields when OK is clicked
        const validationResult = await validateTool(tool);
        setValidationInfo(validationResult);
        
        if (validationResult.isValidName === true &&
            validationResult.isValidDescription === true &&
            validationResult.isValidMicroflow === true &&
            validationResult.isValidType === true) {
            onClose?.(tool);
        } else {
            return;  // Prevent closing if there are validation errors
        }
    }, [onClose, tool, validateTool]);

    const handleCancel = useCallback(() => {
        onClose?.(null);
    }, [onClose]);

    const handleHelp = useCallback(() => {
        window.open("https://docs.mendix.com/appstore/modules/genai/genai-for-mx/agent-commons/#adding-microflows-as-tools", "_blank");
    }, []);

    const validateField = useCallback(async (field: keyof Tool, updatedTool: Tool) => {
        const validationKey = fieldToValidationKey[field];
        
        //rerun validation only if the field is currently invalid
        if (validationKey && validationInfo[validationKey] !== true) {
            const validationResult = await handleValidateTool(field, updatedTool, studioPro, agent);
            setValidationInfo(prev => ({ ...prev, [validationKey]: validationResult }));
        }
    }, [studioPro, agent, validationInfo]);

    const selectMicroflow = useCallback(async () => {
        const updatedTool = await handleSelectCustomDocument(studioPro, tool as Tool, "microflow", "Microflows$Microflow");
        if (updatedTool) {
            setTool(updatedTool);
            validateField('microflow', updatedTool);
        }
    }, [studioPro, tool, validateField]);

    const showMicroflow = useCallback(async () => {
        if (tool.microflow) {
            handleShowMicroflow(studioPro, tool.microflow);
        }
    }, [studioPro, tool.microflow]);

    const handleFieldChange = useCallback((field: keyof Tool) => (value: string) => {
        const updatedTool = { ...tool, [field]: value };
        setTool(updatedTool);
        validateField(field, updatedTool);
    }, [tool, validateField]);

    return (
        <AppThemeProvider studioPro={studioPro}>
            <PageContainerDialog>
                <PageContent>
                    <ContentColumn>
                        <FormDivider label="Common">
                            <ComboBox
                                aria-label="Tool type"
                                label="Tool type"
                                selectedKey={tool.toolType}
                                isDisabled={true} // remove when adding more tool types
                                validate={() => validationInfo.isValidType}
                                onSelectionChange={() => { }}
                            >
                                {toolTypeOptions.map((option) => (
                                    <DropdownListBoxItem key={option.key} id={option.key}>
                                        {option.caption}
                                    </DropdownListBoxItem>
                                ))}
                            </ComboBox>
                            {tool.toolType === "Microflow" && (
                                <>
                                    <TextInputWithButton
                                        ariaLabel="Microflow"
                                        label="Microflow"
                                        value={tool.microflow ? tool.microflow : ''}
                                        icon={tool.microflow ? <MicroflowIcon /> : undefined}
                                        onClick={selectMicroflow}
                                        buttonCaption="Select..."
                                        buttonCaptionSecondary={tool.microflow ? "Show" : undefined}
                                        onClickSecondary={tool.microflow ? showMicroflow : undefined}
                                        validate={() => validationInfo.isValidMicroflow}
                                    />
                                </>
                            )}

                        </FormDivider>
                        {tool.toolType === "Microflow" && (
                            <FormDivider label="Naming">
                                <TextInputLabeled
                                    label="Name"
                                    ariaLabel="Name"
                                    value={tool.name}
                                    onChange={handleFieldChange("name")}
                                    validate={() => validationInfo.isValidName}
                                />
                                <TextAreaLabeled
                                    label="Description"
                                    ariaLabel="Description"
                                    value={tool.description}
                                    onChange={handleFieldChange("description")}
                                    validate={() => validationInfo.isValidDescription}
                                />
                            </FormDivider>
                        )}
                    </ContentColumn>
                </PageContent>
                <DialogFooter
                    onOk={handleOk}
                    onCancel={handleCancel}
                    onHelp={handleHelp}
                />
            </PageContainerDialog>
        </AppThemeProvider>
    );
};
export const component: IComponent = {
    async loaded(componentContext: ComponentContext, componentInput: { dialogId: string; agent: string, tool?: string }) {

        const studioPro = getStudioProApi(componentContext);
        const logger = createStudioProLogger(studioPro);

        try {
            const rootElement = document.getElementById("root");
            if (!rootElement) {
                throw new Error("Failed to find the root element");
            }
            const root = createRoot(rootElement);

            // Decode agent & tool from query parameter
            let parsedTool: Tool | undefined;
            if (componentInput.tool) {
                parsedTool = JSON.parse(decodeURIComponent(componentInput.tool));
            }

            const parsedAgent: Agent = JSON.parse(decodeURIComponent(componentInput.agent));

            const handleClose = (result: Tool | null) => {
                // Set the result on the component context before closing
                studioPro.ui.dialogs.closeWithResult(componentInput.dialogId, result);
            };
            root.render(
                <StrictMode>
                    <App
                        studioPro={studioPro}
                        initialTool={parsedTool}
                        agent={parsedAgent}
                        onClose={handleClose} />
                </StrictMode>
            );
        } catch (error) {
            logger.error("Error editing agent tool:", error);
            throw new Error("Error editing agent tool:", error as Error);
        }
    }
};